-- 1. On the primary: stop writes and confirm the replica is caught up
SELECT client_addr, state, sync_state, replay_lag
FROM pg_stat_replication;

SELECT pg_current_wal_lsn();          -- note this LSN

-- 2. On the standby: confirm it has replayed the same LSN
SELECT pg_last_wal_replay_lsn();

-- 3. On the standby: promote it to primary
SELECT pg_promote();

-- 4. Confirm it now accepts writes
SELECT pg_is_in_recovery();           -- false means it is the new primary
